import numpy as np, json
info = json.load(open("frag_info.json"))
els_f = info["els"]; cC = info["carbene"]
F = np.load("frag_xyz.npy")
nF=len(els_f)
# intra-fragment bonded pairs (constant under rotation)
cov={"H":0.35,"C":0.77,"N":0.72}
intra=set()
for i in range(nF):
    for j in range(i+1,nF):
        if np.linalg.norm(F[i]-F[j])<cov[els_f[i]]+cov[els_f[j]]+0.45: intra.add((i,j))
Cc=F[cC]; N1=F[info["nitrogens"][0]]; N2=F[info["nitrogens"][1]]
mm=0.5*(N1+N2); u=Cc-mm; u/=np.linalg.norm(u)
v=np.cross(N1-Cc,N2-Cc); v/=np.linalg.norm(v); w=np.cross(u,v)
def place(M,uM,th_deg):
    uM=np.array(uM,float); uM/=np.linalg.norm(uM)
    t0=np.array([0,1,0],float); t0=t0-(t0@uM)*uM; t0/=np.linalg.norm(t0)
    w0=np.cross(uM,t0); t_=np.cos(np.radians(th_deg))*t0+np.sin(np.radians(th_deg))*w0
    wt=np.cross(uM,t_)
    R=np.column_stack([uM,t_,wt])@np.column_stack([u,v,w]).T
    Cc_t=np.array(M,float)-2.05*uM
    return (R@(F-Cc).T).T+Cc_t
C1=np.array([-1.91,0,0.]);C2=np.array([-0.69,0,0.]);C3=np.array([0.69,0,0.]);C4=np.array([1.91,0,0.])
