Au2=C4+2.0*np.array([ np.cos(np.radians(12)),0,-np.sin(np.radians(12))])
Cu=0.5*(C1+C2)+np.array([0,0,2.15])
uM1=(C1-Au1)/np.linalg.norm(C1-Au1); uM2=(C4-Au2)/np.linalg.norm(C4-Au2); uM3=np.array([0,0,-1.0])
