import numpy as np, sys
def read(p):
    L=open(p).read().split("\n"); n=int(L[0])
    els=[];xyz=[]
    for line in L[2:2+n]:
        t=line.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els,np.array(xyz)
els,P=read(sys.argv[1] if len(sys.argv)>1 else "opt1.xyz")
def d(i,j): return float(np.linalg.norm(P[i]-P[j]))
